// Functions whose results include the undefined of a fall-through or a
// bare return, comment-like text in literals, a branch no call takes
// that declares a var read outside it, and two such branches that declare
// the same var.

const entries = [
  { key: "a", value: 1 },
  { key: "b", value: 2 },
];

function find(key) {
  for (const entry of entries) {
    if (entry.key === key) return entry;
  }
}

function findOrReturn(key) {
  for (const entry of entries) if (entry.key === key) return entry;
  return;
}

export function lookup(key) {
  const hit = find(key);
  if (hit) {
    return "found " + hit.key + "=" + hit.value;
  } else {
    return "missing " + key;
  }
}

export function lookupOrReturn(key) {
  const hit = findOrReturn(key);
  if (hit) {
    return "found " + hit.key + "=" + hit.value;
  } else {
    return "missing " + key;
  }
}

export function banner(n) {
  const quoted = "/** @type {number} */";
  const template = `/** @returns {string} ${n} */`;
  const pattern = /\/\*\* @param \*\//;
  return quoted + " " + template + " " + pattern.source;
}

function noteOf(extra) {
  if (extra) {
    var note = "set";
  }
  return typeof note + " " + String(note);
}

export function hoisted(label) {
  return label + " " + noteOf(undefined);
}

function levelOf(warn, fail) {
  if (warn) {
    var level = "warn";
  }
  if (fail) {
    var level = "fail";
  }
  return typeof level + " " + String(level);
}

export function shared(label) {
  return label + " " + levelOf(undefined, undefined);
}
